import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.CjAa9jTu.js";const h=JSON.parse('{"title":"Compilación, memoria y archivos de firmware","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compilacion.md","filePath":"guide/compilacion.md"}'),r={name:"guide/compilacion.md"};function l(n,a,s,d,c,p){return i(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="compilacion-memoria-y-archivos-de-firmware" tabindex="-1">Compilación, memoria y archivos de firmware <a class="header-anchor" href="#compilacion-memoria-y-archivos-de-firmware" aria-label="Permalink to &quot;Compilación, memoria y archivos de firmware&quot;">​</a></h1><h2 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to &quot;Objetivo&quot;">​</a></h2><p>Reconocer qué genera Arduino IDE, comprobar que el programa cabe en el PY32F003L24D6TR y conservar los archivos asociados a una prueba.</p><h2 id="compilar-y-leer-el-resultado" tabindex="-1">Compilar y leer el resultado <a class="header-anchor" href="#compilar-y-leer-el-resultado" aria-label="Permalink to &quot;Compilar y leer el resultado&quot;">​</a></h2><ol><li>Abre <a href="./../examples/lab01-blink">01_blink</a>.</li><li>En las preferencias del IDE, activa la salida detallada durante compilación.</li><li>Selecciona <strong>PY32F003x4</strong>, <strong>HSI 24Mhz, HCLK 24Mhz</strong> y <strong>Smallest (-Os default)</strong>.</li><li>Pulsa <strong>Verificar</strong> y lee la consola desde el primer error, si lo hay.</li></ol><table tabindex="0"><thead><tr><th>Dato</th><th>Qué revisar</th></tr></thead><tbody><tr><td>Flash disponible</td><td>El límite debe ser 16 384 bytes</td></tr><tr><td>RAM disponible</td><td>El límite debe ser 2 048 bytes</td></tr><tr><td>Programa utilizado</td><td>Debe caber en la Flash seleccionada</td></tr><tr><td>Variables globales/estáticas</td><td>Deben dejar espacio para pila, búferes y memoria dinámica</td></tr><tr><td>Advertencias</td><td>Determina su causa antes de dar por preparada la estación</td></tr></tbody></table><p>Seleccionar <code>x6</code> o <code>x8</code> permite enlazar para una memoria mayor que la del dispositivo del taller. Comprueba la variante incluso si la compilación pasa.</p><h2 id="archivos-que-genera-el-paquete" tabindex="-1">Archivos que genera el paquete <a class="header-anchor" href="#archivos-que-genera-el-paquete" aria-label="Permalink to &quot;Archivos que genera el paquete&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Archivo</th><th>Contenido</th><th>Uso</th></tr></thead><tbody><tr><td><code>.ino</code></td><td>Código fuente del sketch</td><td>Modificar y conservar la práctica</td></tr><tr><td><code>.elf</code></td><td>Programa enlazado; puede incluir símbolos de depuración</td><td>Inspección y depuración</td></tr><tr><td><code>.hex</code></td><td>Firmware con direcciones</td><td>Formato utilizado por la receta de carga pyOCD</td></tr><tr><td><code>.bin</code></td><td>Imagen binaria sin direcciones incorporadas</td><td>Programación con una dirección de inicio explícita</td></tr><tr><td><code>.map</code></td><td>Distribución de secciones y símbolos</td><td>Analizar el uso de memoria</td></tr></tbody></table><p>En <strong>Programa/Sketch → Exportar binarios compilados</strong>, el IDE guarda los artefactos exportables en la carpeta del sketch, normalmente bajo <code>build/</code>. Revisa la salida detallada para localizar también el <code>.map</code> y los archivos de la carpeta temporal de compilación. Copia allí los que necesites conservar antes de cerrar o limpiar el entorno.</p><div class="tip custom-block"><p class="custom-block-title">Firmware de recuperación</p><p>Compila <code>01_blink</code> con la configuración de la estación y conserva su <code>.hex</code> junto al código y la versión del paquete. Para el taller utiliza un firmware que el instructor haya probado en la placa correspondiente.</p></div><h2 id="compilacion-opcional-por-terminal" tabindex="-1">Compilación opcional por terminal <a class="header-anchor" href="#compilacion-opcional-por-terminal" aria-label="Permalink to &quot;Compilación opcional por terminal&quot;">​</a></h2><p>Si ya tienes <strong>Arduino CLI</strong>, el paquete 0.1.7 y sus herramientas instalados, puedes ejecutar desde la raíz de este repositorio:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arduino-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --fqbn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UNIT_Electronics_PY32:py32:GenF003:pnum=PY32F003x4,ClockSourceAndFrequency=HSI24M_HCLK24M,SupplyVoltage=3V3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/01_blink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docs/public/examples/py32f003/01_blink</span></span></code></pre></div><p>En PowerShell, escribe el comando en una línea o utiliza su sintaxis de continuación. La instrucción compila; la carga de la práctica se realiza con <a href="./../py32f003-getting-started/04_swd">Arduino IDE y SWD</a>.</p><h2 id="comprobacion-de-los-ejemplos-incluidos" tabindex="-1">Comprobación de los ejemplos incluidos <a class="header-anchor" href="#comprobacion-de-los-ejemplos-incluidos" aria-label="Permalink to &quot;Comprobación de los ejemplos incluidos&quot;">​</a></h2><p>Compilación con UNIT Electronics PY32 <strong>0.1.7</strong>, variante <strong>PY32F003x4</strong>, HSI a <strong>24 MHz</strong>, opción <strong>3.3V</strong>, <code>Serial</code> genérico habilitado y optimización <strong>-Os</strong>:</p><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Flash utilizada (bytes)</th><th>RAM estática (bytes)</th></tr></thead><tbody><tr><td>01_blink</td><td>10 656</td><td>1 112</td></tr><tr><td>02_entrada_digital</td><td>10 768</td><td>1 112</td></tr><tr><td>03_uart</td><td>9 704</td><td>1 076</td></tr><tr><td>04_adc</td><td>14 948</td><td>1 124</td></tr><tr><td>05_validacion</td><td>10 648</td><td>1 120</td></tr></tbody></table><p>Los cinco ejemplos caben en la memoria seleccionada. El ejemplo ADC ocupa aproximadamente el 91 % de la Flash; comprueba de nuevo el tamaño si añades funcionalidad. Las cifras de RAM no incluyen todo el consumo de pila en ejecución.</p><p>El paquete emite una advertencia de declaración implícita de <code>READ_BIT</code> en su archivo <code>system_py32f0xx.c</code>, dentro de <code>SystemCoreClockUpdate</code>. Estos ejemplos enlazan correctamente con la configuración indicada. Conserva esa advertencia en el registro de la estación y revísala al cambiar el core o añadir código que utilice esa función. El origen es el paquete de la placa.</p><p>Esta comprobación verifica compilación y enlace; el instructor debe completar la carga SWD y las pruebas físicas descritas en cada laboratorio.</p><h2 id="comparacion-entre-versiones" tabindex="-1">Comparación entre versiones <a class="header-anchor" href="#comparacion-entre-versiones" aria-label="Permalink to &quot;Comparación entre versiones&quot;">​</a></h2><p>Compila Blink con intervalos de 500 ms y 250 ms y registra los tamaños. Cambiar un valor constante puede cambiar el comportamiento sin modificar el tamaño final. La comprobación sobre la placa permite identificar esa diferencia.</p><p>Conserva para cada prueba: fuente, configuración, versión de herramientas, artefacto programado y resultado observado. Continúa con el <a href="./../examples/lab05-validacion">laboratorio de validación</a>.</p>`,24)])])}const u=e(r,[["render",l]]);export{h as __pageData,u as default};
